		for (j = i; j > insert_idx; j--)
			parser->args[j + offset] = parser->args[j - 1];
		parser->args[insert_idx] = option;
		if (value)
			parser->args[insert_idx + 1] = value;
		insert_idx += (1 + offset);
		i += offset;
		changed = 1;
