1104	/// Parses the bare argument at the parser's position, which it moves past: the outcome of the
1105	/// spec [`find_arg`] gives it, or [`Status::UnknownOption`] when every argument spec is taken.
1106	///
1107	/// A [`Kind::Arg`] spec stores the argument in its variable; a [`Kind::Args`] spec stores where
1108	/// the remaining arguments start, this one included, in its [`ArgsSlot`], counts them as the
1109	/// outcome's and the parser's [`args_len`](OptRef::args_len), and moves the parser past them all.
1110	///
1111	/// Replaces `fn::parse_arg`
1112	#[doc(alias = "parse_arg")]
1113	fn take_bare<'p>(parser: &mut ParserMut<'_, 'p>) -> Opt<'p> {
1114	    let mut opt = Opt::zeroed();
1115	    let spec = find_arg(parser);
1116	    let (idx, len) = (parser.as_ref().idx(), parser.as_ref().args_len());
1117	    let arg = parser.as_ref().args().get(idx).copied();
1118	    let mut out = opt.as_mut();
1119	    out.set_spec(spec);
1120	    out.set_arg(arg.map(Arg::as_c_str));
1121	    let Some(spec) = spec else {
1122	        parser.set_idx(idx + 1);
1123	        out.set_status(Status::UnknownOption);
1124	        return opt;
1125	    };
1126	    match spec.target() {
1127	        Some(Target::Args(slot)) => {
1128	            if let Some(slot) = slot {
1129	                slot.set(parser.as_ref().args().get(idx..).unwrap_or_default());
1130	            }
1131	            let taken = len.saturating_sub(idx);
1132	            parser.set_in_args(taken);
1133	            parser.set_idx(len);
1134	            out.set_args_len(taken);
1135	        }
1136	        target => {
1137	            if let Some(Target::Arg(Some(variable))) = target {
1138	                variable.set(arg);
1139	            }
1140	            parser.set_idx(idx + 1);
1141	        }
1142	    }
1143	    out.set_status(Status::Ok);
