1241	    /// Parses the argument at the parser's position, or the next option of the bundle it is in,
1242	    /// and moves past it: its outcome, with the spec it matched, the argument as given and the
1243	    /// value it took, and [`Status::Done`] once no argument is left, which reports how many
1244	    /// arguments a [`Kind::Args`] spec took, if one did. The specs' variables are written as the
1245	    /// argument selects them.
1246	    ///
1247	    /// An argument that starts with `--` is a long option, `--name`, `--name=value` or
1248	    /// `--no-name`, and one that starts with `-` a short option or a bundle of them, `-abc` or
1249	    /// `-ovalue`: each is looked up among the table's options, and one the table does not have is
1250	    /// [`Status::UnknownOption`]. A [`Kind::Value`] option given no value takes the next
1251	    /// argument, or is [`Status::MissingValue`] when none is left and its value is not optional.
1252	    /// Any other argument is bare, as is every argument after a literal `--`: it takes the next of
1253	    /// the table's [`Kind::Arg`] specs, in order, or a [`Kind::Args`] spec, which takes every
1254	    /// argument left; once they are taken, a bare argument is [`Status::UnknownOption`]. An
1255	    /// option of a choice ([`Usage::CHOICE`]) given counts the choice's argument specs as taken.
1256	    ///
1257	    /// A parser that parses GNU style, as [`Parser::new`] decides, reorders its arguments at the
1258	    /// first bare one it meets, moving the options after it, with their values, ahead of it,
1259	    /// so that options may follow bare arguments, as `file1 --help file2`; it parses in the
1260	    /// order given otherwise, every argument after the first bare one being bare.
1261	    ///
1262	    /// ```
1263	    /// use core::cell::Cell;
1264	    ///
1265	    /// use libgit2_crustify::git2::src::cli::opt::{
1266	    ///     Arg, ParseFlags, Parser, Spec, SpecTable, Status, Target,
1267	    /// };
1268	    ///
1269	    /// let (debug, file) = (Cell::new(0), Cell::new(None));
1270	    /// let specs = [
1271	    ///     Spec::new(Target::Bool(Some(&debug))).with_name(c"debug"),
1272	    ///     Spec::new(Target::Arg(Some(&file))),
1273	    ///     Spec::default(),
1274	    /// ];
1275	    /// let table = SpecTable::new(&specs).unwrap();
1276	    /// let mut args = [c"notes.txt", c"--debug"].map(Arg::new);
1277	    /// let mut parser = Parser::new(table, &mut args, ParseFlags::FORCE_GNU);
1278	    /// let mut parser = parser.as_mut();
1279	    /// let first = parser.parse_next();
1280	    /// assert_eq!(first.as_ref().status(), Some(Status::Ok));
1281	    /// assert_eq!(first.as_ref().arg(), Some(c"--debug"));
1282	    /// assert_eq!(parser.parse_next().as_ref().arg(), Some(c"notes.txt"));
1283	    /// assert_eq!(parser.parse_next().as_ref().status(), Some(Status::Done));
1284	    /// assert_eq!(debug.get(), 1);
1285	    /// assert_eq!(file.get().map(Arg::as_c_str), Some(c"notes.txt"));
1286	    /// ```
1287	    ///
1288	    /// The C defects [`find_long`], [`find_short`], [`skip_choice_args`], [`take_short`] and
1289	    /// [`reorder_gnu_style`] list are not carried over: a parser that has no table, as a zeroed
1290	    /// one, finds no spec, and its arguments are unknown, where the C reads through a null
1291	    /// pointer.
1292	    ///
1293	    /// Replaces `fn::cli_opt_parser_next`
1294	    #[doc(alias = "cli_opt_parser_next")]
1295	    #[must_use]
1296	    pub fn parse_next(&mut self) -> Opt<'p> {
1297	        loop {
1298	            let state = self.as_ref();
1299	            let Some(arg) = state.args().get(state.idx()).copied() else {
1300	                let mut done = Opt::zeroed();
1301	                done.as_mut().set_args_len(state.in_args());
1302	                return done;
1303	            };
1304	            let bytes = arg.as_c_str().to_bytes();
1305	            let (in_short, in_literal) = (state.in_short() != 0, state.in_literal());
1306	            if bytes.starts_with(b"--") && !in_short && !in_literal {
1307	                return take_long(self);
1308	            }
1309	            if in_short || (bytes.starts_with(b"-") && !in_literal) {
1310	                return take_short(self);
1311	            }
1312	            if !(state.needs_sort() && reorder_gnu_style(self)) {
1313	                return take_bare(self);
1314	            }
1315	        }
1316	    }
1317	}
