1319	/// Parses every argument of `args` against `specs` under `flags`, as a [`Parser`] does, and
1320	/// checks that each required spec ([`Usage::REQUIRED`]) was given, or one option of a required
1321	/// choice: the [`Status::Done`] outcome and the arguments in the order the parse left them, which
1322	/// a GNU-style parse may have changed, and in which a [`Kind::Args`] spec's [`ArgsSlot`] finds what
1323	/// it took. The specs' variables hold what the arguments gave them.
1324	///
1325	/// An argument that ends parsing ([`Usage::STOP_PARSING`]), as a command's `--help`, ends it
1326	/// there, unchecked: the outcome is that argument's, its status [`Status::Done`].
1327	///
1328	/// ```
1329	/// use core::cell::Cell;
1330	///
1331	/// use libgit2_crustify::git2::src::cli::opt::{
1332	///     Arg, ArgsSlot, ParseFlags, Spec, SpecTable, Status, Target, Usage, parse,
1333	/// };
1334	///
1335	/// let (quiet, paths) = (Cell::new(0), ArgsSlot::new());
1336	/// let specs = [
1337	///     Spec::new(Target::Bool(Some(&quiet))).with_alias(b'q'),
1338	///     Spec::new(Target::Args(Some(&paths))).with_usage(Usage::REQUIRED),
1339	///     Spec::default(),
1340	/// ];
1341	/// let table = SpecTable::new(&specs).unwrap();
1342	/// let mut args = [c"a.txt", c"-q", c"b.txt"].map(Arg::new);
1343	/// let (done, args) = parse(table, &mut args, ParseFlags::FORCE_GNU).unwrap();
1344	/// assert_eq!(done.as_ref().args_len(), 2);
1345	/// let taken: Vec<_> = paths
1346	///     .get_in(args)
1347	///     .unwrap()
1348	///     .iter()
1349	///     .map(|a| a.as_c_str())
1350	///     .collect();
1351	/// assert_eq!(taken, [c"a.txt", c"b.txt"]);
1352	/// assert_eq!(quiet.get(), 1);
1353	/// ```
1354	///
1355	/// The parse borrows the arguments for as long as the variables it wrote, which hold them, are
1356	/// in use, so they cannot be changed meanwhile; the arguments it hands back are that borrow's:
1357	///
1358	/// ```compile_fail,E0506
1359	/// use core::cell::Cell;
1360	///
1361	/// use libgit2_crustify::git2::src::cli::opt::{Arg, ParseFlags, Spec, SpecTable, Target, parse};
1362	///
1363	/// let file = Cell::new(None);
1364	/// let specs = [Spec::new(Target::Arg(Some(&file))), Spec::default()];
1365	/// let table = SpecTable::new(&specs).unwrap();
1366	/// let mut args = [Arg::new(c"a")];
1367	/// let _ = parse(table, &mut args, ParseFlags::DEFAULT);
1368	/// args[0] = Arg::new(c"b");
1369	/// let _ = file.get();
1370	/// ```
1371	///
1372	/// # Errors
1373	///
1374	/// The outcome of the first argument that fails, an [`Status::UnknownOption`] or a
1375	/// [`Status::MissingValue`], at which the parse stops; or, once every argument is parsed, a
1376	/// [`Status::MissingArgument`] outcome whose spec is the first requirement not given, the first
1377	/// spec of its choice.
1378	///
1379	/// The C keeps the specs the arguments gave in a stack array of one entry per argument, and a
1380	/// bundle of short options gives one per option, so that `-ab` writes past it: here they are
1381	/// kept in a [`Vec`], with no bound.
1382	///
1383	/// Replaces `fn::cli_opt_parse`
1384	#[doc(alias = "cli_opt_parse")]
1385	pub fn parse<'p>(
1386	    specs: SpecTable<'p>,
1387	    args: &'p mut [Arg<'p>],
1388	    flags: ParseFlags,
1389	) -> Result<(Opt<'p>, &'p [Arg<'p>]), Opt<'p>> {
1390	    let mut parser = Parser::new(specs, args, flags);
1391	    let mut given = Vec::new();
1392	    let (mut outcome, stopped) = loop {
1393	        let mut opt = parser.as_mut().parse_next();
1394	        match opt.as_ref().status() {
1395	            Some(Status::Ok) => {}
1396	            Some(Status::Done) => break (opt, false),
1397	            _ => return Err(opt),
1398	        }
1399	        if let Some(spec) = opt.as_ref().spec() {
1400	            if spec.usage().contains(Usage::STOP_PARSING) {
1401	                opt.as_mut().set_status(Status::Done);
1402	                break (opt, true);
1403	            }
1404	            given.push(spec);
1405	        }
1406	    };
1407	    if !stopped && let Err(missing) = check_required(specs, &given) {
1408	        let mut out = outcome.as_mut();
1409	        out.set_spec(Some(missing));
1410	        out.set_status(Status::MissingArgument);
1411	        return Err(outcome);
1412	    }
1413	    Ok((outcome, parser.into_args()))
1414	}
