3088	        /// Calls the callback with `opt`, the outcome of one argument: whether the parse goes
3089	        /// on, or stops with the code the callback breaks with. A C function's return is the
3090	        /// code, 0 going on.
3091	        pub fn call(&mut self, opt: OptRef<'_, 'p>) -> ControlFlow<NonZero<c_int>> {
3092	            match &mut self.0 {
3093	                ForeachInner::Rust(f) => f(opt),
3094	                ForeachInner::C(f) => {
3095	                    // SAFETY: `from_c`'s contract makes `f` callable with its context now, on
3096	                    // this thread; `opt` is a live outcome that lends what it points at for
3097	                    // `'p`, which `f` only reads during the call, so the pointer's write
3098	                    // permission is never used.
3099	                    let rc = unsafe { f.call((opt.as_ptr().cast_mut(),)) };
3100	                    NonZero::new(rc).map_or(ControlFlow::Continue(()), ControlFlow::Break)
3101	                }
3102	            }
3103	        }
3104	    }
