3212	        /// One step of C's parser, `cli_opt_parser_next`.
3213	        fn c_next<'p>(opt: &mut Opt<'p>, parser: &mut Parser<'p>) -> Option<Status> {
3214	            // SAFETY: both are live values Rust holds, borrowed exclusively for the call; the
3215	            // parser's table and arguments are borrowed for `'p`, so what C stores in the outcome
3216	            // and the specs' variables lives as long as they do.
3217	            let raw = unsafe {
3218	                sys::cli_opt_parser_next(opt.as_mut().as_mut_ptr(), parser.as_mut().as_mut_ptr())
3219	            };
3220	            Status::from_raw(raw)
3221	        }
