3223	        /// The first outcome C's parser gives `arg` alone, against `table`, and the parser after
3224	        /// it.
3225	        fn c_first<'p>(table: SpecTable<'p>, args: &'p mut [Arg<'p>]) -> (Opt<'p>, Parser<'p>) {
3226	            let mut parser = Parser::new(table, args, ParseFlags::DEFAULT);
3227	            let mut opt = Opt::zeroed();
3228	            c_next(&mut opt, &mut parser);
3229	            (opt, parser)
3230	        }
