3232	        /// Where a spec C or Rust found is in `table`.
3233	        fn index(table: SpecTable<'_>, spec: Option<SpecRef<'_, '_>>) -> Option<usize> {
3234	            spec.map(|s| {
3235	                let offset = s.as_ptr().addr() - table.get(0).unwrap().as_ptr().addr();
3236	                offset / size_of::<Spec<'_>>()
3237	            })
3238	        }
