3757	        /// The write function of an [`Interrupted`] stream.
3758	        ///
3759	        /// # Safety
3760	        ///
3761	        /// `cookie` is the stream's [`Sink`], which only the stream reaches while it is open, and
3762	        /// `buf` addresses `size` readable bytes.
3763	        unsafe extern "C" fn take(cookie: *mut c_void, buf: *const c_char, size: usize) -> isize {
3764	            // SAFETY: the caller's contract: the sink is live, and reached by this call alone.
3765	            let sink = unsafe { &mut *cookie.cast::<Sink>() };
3766	            // SAFETY: the caller's contract: `buf` holds `size` bytes.
3767	            let bytes = unsafe { core::slice::from_raw_parts(buf.cast::<u8>(), size) };
3768	            let taken = if sink.fail { size.min(3) } else { size };
3769	            sink.bytes.extend_from_slice(&bytes[..taken]);
3770	            if taken < size {
3771	                sink.fail = false;
3772	                glibc_bindings::libc::csu::errno_loc::set_errno(libc::EINTR);
3773	            }
3774	            isize::try_from(taken).unwrap_or(isize::MAX)
3775	        }
