                // stream holds nothing to flush.
                unsafe { libc::fclose(self.file) };
                // SAFETY: `open`'s box, which the closed stream no longer reaches, taken back
                // once.
                unsafe { Box::from_raw(self.sink) }.bytes
            }
        }

