            unsafe { libc::fclose(file) };
            let e = written.unwrap_err();
            assert_eq!(e.raw_os_error(), Some(c_errno));
            assert_eq!(e.raw_os_error(), Some(nix::errno::Errno::EBADF as c_int));
            assert!(storage.iter().all(|&b| b == 0));
        }
    }
}

