            // field is plain data. The array is borrowed exclusively for `'p`, as `args()`
            // and `args_mut()` require, with its length written beside it.
            unsafe { args_ptr.write(args) };
            // SAFETY: as above.
            unsafe { len_ptr.write(len) };
