            assert!(done.spec.is_null());
            assert_eq!(done.args_len, 2);
            assert_eq!(argv.strings(), ["hash-object", "-w", "-tblob", "a.txt", "b.txt"]);
            assert_eq!(write.get(), 1);
            assert_eq!(kind.get().map(|k| k.as_c_str()), Some(c"blob"));
            let first = files.get_in(&[]);
