        /// The value a [`Kind::Switch`] spec sets, or a [`Kind::Accumulator`] spec adds, `1`
        /// standing in for `0` there; other kinds ignore it.
        ///
        /// Wraps `fld::cli_opt_spec.switch_value`
        #[doc(alias = "cli_opt_spec.switch_value")]
        #[must_use]
